import React, { useState, useEffect } from "react"
import { format } from "date-fns"
import { TaxSettings } from "../../../hooks/useSettings"
import { useToast } from "../../../context/ToastContext"

// Quebec statutory rates:
//   GST: 5%      (federal, Canada Revenue Agency)
//   QST: 9.975%  (provincial, Revenu Québec)

interface TaxesConfigProps {
  taxes: TaxSettings
  updateTaxes: (gst: number, qst: number, adminEmail: string) => Promise<void>
  adminEmail: string
}

function round2(n: number) {
  return Math.round(n * 100) / 100
}

function validateRate(v: string): string {
  const n = parseFloat(v)
  if (isNaN(n) || v.trim() === "") return "Required"
  if (n <= 0) return "Must be greater than 0"
  if (n > 50) return "Must be 50 or less"
  if (!/^\d+(\.\d{1,2})?$/.test(v.trim())) return "Max 2 decimal places"
  return ""
}

export default function TaxesConfig({ taxes, updateTaxes, adminEmail }: TaxesConfigProps) {
  const { showToast } = useToast()
  const [gstInput, setGstInput] = useState(String(taxes.GST))
  const [qstInput, setQstInput] = useState(String(taxes.QST))
  const [gstError, setGstError] = useState("")
  const [qstError, setQstError] = useState("")
  const [isSaving, setIsSaving] = useState(false)
  const [isDirty, setIsDirty] = useState(false)

  useEffect(() => {
    setGstInput(String(taxes.GST))
    setQstInput(String(taxes.QST))
    setIsDirty(false)
  }, [taxes.GST, taxes.QST])

  function handleGstChange(v: string) {
    setGstInput(v)
    setGstError(validateRate(v))
    setIsDirty(true)
  }

  function handleQstChange(v: string) {
    setQstInput(v)
    setQstError(validateRate(v))
    setIsDirty(true)
  }

  async function handleSave() {
    const gstErr = validateRate(gstInput)
    const qstErr = validateRate(qstInput)
    setGstError(gstErr)
    setQstError(qstErr)
    if (gstErr || qstErr) return

    setIsSaving(true)
    try {
      await updateTaxes(parseFloat(gstInput), parseFloat(qstInput), adminEmail)
      setIsDirty(false)
      showToast("Tax rates saved", "success")
    } catch {
      showToast("Failed to save tax rates", "error")
    } finally {
      setIsSaving(false)
    }
  }

  const gstVal = parseFloat(gstInput) || 0
  const qstVal = parseFloat(qstInput) || 0
  const base = 100
  const previewGST = round2(base * gstVal / 100)
  const previewQST = round2(base * qstVal / 100)
  const previewTotal = round2(base + previewGST + previewQST)

  const canSave = isDirty && !gstError && !qstError && !isSaving

  return (
    <div className="space-y-5">
      {/* Warning banner */}
      {isDirty && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg px-4 py-3 text-sm text-yellow-800">
          ⚠️ Tax rate changes apply to new service tickets only. Existing records retain the rates at time of creation.
        </div>
      )}

      <div className="bg-white rounded-xl shadow-sm p-6 space-y-5">
        <div>
          <h2 className="text-sm font-semibold text-gray-700 mb-0.5">Tax Rates</h2>
          {taxes.updatedAt && (
            <p className="text-xs text-gray-400">
              Last updated: {format(taxes.updatedAt, "MMM d, yyyy 'at' h:mm a")}
              {taxes.updatedBy ? ` by ${taxes.updatedBy}` : ""}
            </p>
          )}
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">
              Federal Tax (GST) %
            </label>
            <input
              type="number"
              step="0.01"
              min="0.01"
              max="50"
              value={gstInput}
              onChange={e => handleGstChange(e.target.value)}
              disabled={isSaving}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
            />
            {gstError && <p className="text-xs text-red-500 mt-0.5">{gstError}</p>}
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">
              Provincial Tax (QST) %
            </label>
            <input
              type="number"
              step="0.01"
              min="0.01"
              max="50"
              value={qstInput}
              onChange={e => handleQstChange(e.target.value)}
              disabled={isSaving}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
            />
            {qstError && <p className="text-xs text-red-500 mt-0.5">{qstError}</p>}
          </div>
        </div>

        <button
          onClick={handleSave}
          disabled={!canSave}
          className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {isSaving ? "Saving…" : "Save Changes"}
        </button>
      </div>

      {/* Live preview */}
      <div className="bg-white rounded-xl shadow-sm p-6">
        <h3 className="text-sm font-semibold text-gray-700 mb-3">Preview</h3>
        <p className="text-xs text-gray-500 mb-3">On a $100.00 service:</p>
        <div className="space-y-1.5 text-sm font-mono">
          <div className="flex justify-between">
            <span className="text-gray-500">GST ({gstVal}%)</span>
            <span className="text-gray-800">$ {previewGST.toFixed(2)}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-gray-500">QST ({qstVal}%)</span>
            <span className="text-gray-800">$ {previewQST.toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-gray-500 border-t border-gray-100 pt-1.5">
            <span>Tax Total</span>
            <span>$ {round2(previewGST + previewQST).toFixed(2)}</span>
          </div>
          <div className="flex justify-between font-bold text-gray-900 border-t border-gray-200 pt-1.5">
            <span>Grand Total</span>
            <span>$ {previewTotal.toFixed(2)}</span>
          </div>
        </div>
      </div>
    </div>
  )
}
