import React, { useState } from "react"
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from "@dnd-kit/core"
import {
  SortableContext,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import { ServiceItem } from "../../../hooks/useSettings"
import { useToast } from "../../../context/ToastContext"

interface ServicesManagerProps {
  allServices: ServiceItem[]
  addService: (label: string) => Promise<void>
  updateService: (id: string, label: string) => Promise<void>
  toggleService: (id: string, isActive: boolean) => Promise<void>
  reorderServices: (orderedIds: string[]) => Promise<void>
}

interface SortableItemProps {
  item: ServiceItem
  isSaving: boolean
  onUpdateLabel: (id: string, label: string) => Promise<void>
  onToggle: (id: string, isActive: boolean) => void
}

function SortableItem({ item, isSaving, onUpdateLabel, onToggle }: SortableItemProps) {
  const [editing, setEditing] = useState(false)
  const [editValue, setEditValue] = useState(item.label)
  const [editError, setEditError] = useState("")

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: item.id,
    disabled: !item.isActive || isSaving,
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1,
  }

  function startEdit() {
    setEditValue(item.label)
    setEditError("")
    setEditing(true)
  }

  async function commitEdit() {
    const trimmed = editValue.trim()
    if (!trimmed) {
      setEditError("Name cannot be empty")
      return
    }
    if (trimmed === item.label) {
      setEditing(false)
      return
    }
    await onUpdateLabel(item.id, trimmed)
    setEditing(false)
  }

  function cancelEdit() {
    setEditing(false)
    setEditError("")
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={`flex items-center gap-3 px-4 py-3 border-b border-gray-100 last:border-0 ${
        item.isActive ? "bg-white" : "bg-gray-50"
      }`}
    >
      {/* Drag handle — active only */}
      <span
        {...(item.isActive ? { ...attributes, ...listeners } : {})}
        className={`text-gray-400 select-none text-lg leading-none ${
          item.isActive && !isSaving ? "cursor-grab active:cursor-grabbing" : "cursor-default opacity-30"
        }`}
        title={item.isActive ? "Drag to reorder" : undefined}
      >
        ≡
      </span>

      {/* Label / inline editor */}
      <div className="flex-1 min-w-0">
        {editing ? (
          <div>
            <input
              autoFocus
              value={editValue}
              onChange={e => { setEditValue(e.target.value); setEditError("") }}
              onBlur={commitEdit}
              onKeyDown={e => {
                if (e.key === "Enter") { e.preventDefault(); commitEdit() }
                if (e.key === "Escape") cancelEdit()
              }}
              className="w-full border border-blue-400 rounded px-2 py-0.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            {editError && <p className="text-xs text-red-500 mt-0.5">{editError}</p>}
          </div>
        ) : (
          <span
            onDoubleClick={!isSaving ? startEdit : undefined}
            title="Double-click to edit"
            className={`text-sm font-medium select-none ${
              item.isActive ? "text-gray-800 cursor-text" : "text-gray-400 line-through"
            }`}
          >
            {item.label}
          </span>
        )}
      </div>

      {/* Badge */}
      <span
        className={`text-xs px-2 py-0.5 rounded-full font-medium ${
          item.isActive ? "bg-green-100 text-green-700" : "bg-gray-200 text-gray-500"
        }`}
      >
        {item.isActive ? "Active" : "Inactive"}
      </span>

      {/* Toggle button */}
      <button
        onClick={() => onToggle(item.id, !item.isActive)}
        disabled={isSaving}
        className={`text-xs px-3 py-1 rounded-lg border transition-colors disabled:opacity-50 ${
          item.isActive
            ? "border-red-200 text-red-600 hover:bg-red-50"
            : "border-green-200 text-green-600 hover:bg-green-50"
        }`}
      >
        {item.isActive ? "Deactivate" : "Activate"}
      </button>
    </div>
  )
}

export default function ServicesManager({
  allServices,
  addService,
  updateService,
  toggleService,
  reorderServices,
}: ServicesManagerProps) {
  const { showToast } = useToast()
  const [isSaving, setIsSaving] = useState(false)
  const [addingNew, setAddingNew] = useState(false)
  const [newLabel, setNewLabel] = useState("")
  const [newError, setNewError] = useState("")
  const [confirmToggle, setConfirmToggle] = useState<{ id: string; isActive: boolean } | null>(null)

  const active = [...allServices].filter(s => s.isActive).sort((a, b) => a.order - b.order)
  const inactive = allServices.filter(s => !s.isActive)

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  )

  async function handleDragEnd(event: DragEndEvent) {
    const { active: dragActive, over } = event
    if (!over || dragActive.id === over.id) return
    const oldIdx = active.findIndex(s => s.id === dragActive.id)
    const newIdx = active.findIndex(s => s.id === over.id)
    const reordered = arrayMove(active, oldIdx, newIdx)
    setIsSaving(true)
    try {
      await reorderServices(reordered.map(s => s.id))
      showToast("Order saved", "success")
    } catch {
      showToast("Failed to save order", "error")
    } finally {
      setIsSaving(false)
    }
  }

  async function handleUpdateLabel(id: string, label: string) {
    setIsSaving(true)
    try {
      await updateService(id, label)
      showToast("Service updated", "success")
    } catch {
      showToast("Failed to update service", "error")
    } finally {
      setIsSaving(false)
    }
  }

  function requestToggle(id: string, isActive: boolean) {
    if (!isActive) {
      // activating — no confirmation needed
      doToggle(id, isActive)
    } else {
      setConfirmToggle({ id, isActive })
    }
  }

  async function doToggle(id: string, isActive: boolean) {
    setConfirmToggle(null)
    setIsSaving(true)
    try {
      await toggleService(id, !isActive)
      showToast(isActive ? "Service deactivated" : "Service activated", "success")
    } catch {
      showToast("Failed to update service", "error")
    } finally {
      setIsSaving(false)
    }
  }

  async function handleAdd() {
    const trimmed = newLabel.trim()
    if (!trimmed) { setNewError("Name cannot be empty"); return }
    setIsSaving(true)
    try {
      await addService(trimmed)
      setNewLabel("")
      setAddingNew(false)
      showToast("Service added", "success")
    } catch {
      showToast("Failed to add service", "error")
    } finally {
      setIsSaving(false)
    }
  }

  const allItems = [...active, ...inactive]

  return (
    <div className="bg-white rounded-xl shadow-sm overflow-hidden">
      <div className="px-4 py-3 border-b border-gray-100 flex items-center justify-between">
        <h2 className="text-sm font-semibold text-gray-700">Regular Services</h2>
        <p className="text-xs text-gray-400">Double-click a name to edit · Drag ≡ to reorder</p>
      </div>

      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <SortableContext items={active.map(s => s.id)} strategy={verticalListSortingStrategy}>
          {allItems.map(item => (
            <SortableItem
              key={item.id}
              item={item}
              isSaving={isSaving}
              onUpdateLabel={handleUpdateLabel}
              onToggle={requestToggle}
            />
          ))}
        </SortableContext>
      </DndContext>

      {/* Add new service */}
      <div className="px-4 py-3 border-t border-gray-100">
        {addingNew ? (
          <div className="flex gap-2 items-start">
            <div className="flex-1">
              <input
                autoFocus
                value={newLabel}
                onChange={e => { setNewLabel(e.target.value); setNewError("") }}
                onKeyDown={e => {
                  if (e.key === "Enter") handleAdd()
                  if (e.key === "Escape") { setAddingNew(false); setNewLabel(""); setNewError("") }
                }}
                placeholder="Service name"
                className="w-full border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              {newError && <p className="text-xs text-red-500 mt-0.5">{newError}</p>}
            </div>
            <button
              onClick={handleAdd}
              disabled={isSaving}
              className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition-colors disabled:opacity-50"
            >
              Add
            </button>
            <button
              onClick={() => { setAddingNew(false); setNewLabel(""); setNewError("") }}
              className="px-3 py-1.5 border border-gray-200 text-gray-600 hover:bg-gray-50 text-sm rounded-lg transition-colors"
            >
              Cancel
            </button>
          </div>
        ) : (
          <button
            onClick={() => setAddingNew(true)}
            disabled={isSaving}
            className="text-sm text-blue-600 hover:text-blue-700 font-medium disabled:opacity-50"
          >
            + Add Service
          </button>
        )}
      </div>

      {/* Deactivate confirmation */}
      {confirmToggle && (
        <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-sm w-full p-6">
            <h3 className="font-semibold text-gray-800 mb-2">Deactivate service?</h3>
            <p className="text-sm text-gray-600 mb-5">
              This service will no longer appear in new appointments. Existing records are not affected.
            </p>
            <div className="flex gap-3 justify-end">
              <button
                onClick={() => setConfirmToggle(null)}
                className="px-4 py-2 border border-gray-200 text-gray-700 text-sm rounded-lg hover:bg-gray-50 transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => doToggle(confirmToggle.id, confirmToggle.isActive)}
                className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white text-sm rounded-lg transition-colors"
              >
                Deactivate
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
