import React, { useState } from "react"
import { graphql } from "gatsby"
import { useRequireAuth } from "../../hooks/useRequireAuth"
import { useSettings } from "../../hooks/useSettings"
import AdminLayout from "../../components/admin/AdminLayout"
import ServicesManager from "../../components/admin/Settings/ServicesManager"
import TaxesConfig from "../../components/admin/Settings/TaxesConfig"
import BusinessInfo from "../../components/admin/Settings/BusinessInfo"

type Tab = "services" | "taxes" | "business"

export default function SettingsPage() {
  const { currentUser, loading: authLoading } = useRequireAuth()
  const [activeTab, setActiveTab] = useState<Tab>("services")
  const {
    allServices,
    taxes,
    loading,
    addService,
    updateService,
    toggleService,
    reorderServices,
    updateTaxes,
  } = useSettings()

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  const tabs: { key: Tab; label: string }[] = [
    { key: "services", label: "Services" },
    { key: "taxes", label: "Taxes" },
    { key: "business", label: "Business Info" },
  ]

  return (
    <AdminLayout currentPath="/admin/settings">
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Settings</h1>
        <p className="text-sm text-gray-500 mt-0.5">Manage services, tax rates, and business information.</p>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 mb-6 border-b border-gray-200">
        {tabs.map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px ${
              activeTab === tab.key
                ? "border-blue-600 text-blue-600"
                : "border-transparent text-gray-500 hover:text-gray-700"
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="bg-white rounded-xl shadow-sm p-8 flex justify-center">
          <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : (
        <>
          {activeTab === "services" && (
            <ServicesManager
              allServices={allServices}
              addService={addService}
              updateService={updateService}
              toggleService={toggleService}
              reorderServices={reorderServices}
            />
          )}
          {activeTab === "taxes" && (
            <TaxesConfig
              taxes={taxes}
              updateTaxes={updateTaxes}
              adminEmail={currentUser.email ?? ""}
            />
          )}
          {activeTab === "business" && <BusinessInfo />}
        </>
      )}
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
