import React, { useState, useEffect } from "react"
import { doc, onSnapshot, setDoc } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { useToast } from "../../../context/ToastContext"

interface BusinessData {
  name: string
  phone: string
  email: string
  address: string
}

const DEFAULTS: BusinessData = { name: "", phone: "", email: "", address: "" }

export default function BusinessInfo() {
  const { showToast } = useToast()
  const [saved, setSaved] = useState<BusinessData>(DEFAULTS)
  const [form, setForm] = useState<BusinessData>(DEFAULTS)
  const [loading, setLoading] = useState(true)
  const [isSaving, setIsSaving] = useState(false)

  useEffect(() => {
    if (!db) { setLoading(false); return }
    const unsub = onSnapshot(doc(db, "settings", "business"), snap => {
      const d = snap.data() as BusinessData | undefined
      const data = d ?? DEFAULTS
      setSaved(data)
      setForm(data)
      setLoading(false)
    })
    return unsub
  }, [])

  const isDirty =
    form.name !== saved.name ||
    form.phone !== saved.phone ||
    form.email !== saved.email ||
    form.address !== saved.address

  async function handleSave() {
    if (!db) return
    setIsSaving(true)
    try {
      await setDoc(doc(db, "settings", "business"), form)
      showToast("Business info saved", "success")
    } catch {
      showToast("Failed to save", "error")
    } finally {
      setIsSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="bg-white rounded-xl shadow-sm p-8 flex justify-center">
        <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  const fields: { key: keyof BusinessData; label: string; type?: string; placeholder?: string }[] = [
    { key: "name", label: "Shop Name", placeholder: "Garage Carlos Inc." },
    { key: "phone", label: "Phone", type: "tel", placeholder: "514-555-0000" },
    { key: "email", label: "Email", type: "email", placeholder: "info@example.com" },
    { key: "address", label: "Address", placeholder: "123 Main St, Montréal, QC" },
  ]

  return (
    <div className="bg-white rounded-xl shadow-sm p-6 space-y-5">
      <div>
        <h2 className="text-sm font-semibold text-gray-700 mb-0.5">Business Information</h2>
        <p className="text-xs text-gray-400">
          Used in client portal emails and the portal footer.
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {fields.map(({ key, label, type = "text", placeholder }) => (
          <div key={key} className={key === "address" ? "sm:col-span-2" : ""}>
            <label className="block text-xs font-medium text-gray-600 mb-1">{label}</label>
            <input
              type={type}
              value={form[key]}
              onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))}
              placeholder={placeholder}
              disabled={isSaving}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
            />
          </div>
        ))}
      </div>

      <button
        onClick={handleSave}
        disabled={!isDirty || isSaving}
        className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
      >
        {isSaving ? "Saving…" : "Save"}
      </button>
    </div>
  )
}
